(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0014.js"] = [{"id":"glyph-seal-4eac","script":"seal","character":"京","reading":"jīng","description":"jīng：(1)国都（现特指中国首都北京）～城。～都。～华（因京都是文物、人才汇集的地方，所以称京都为京华”）。～畿（国都和国都附近的地方）。～剧。～师（首都的旧称）。～绣。～菜。\n(2)大。\n(3)古代数名，指一千万，亦指一亿兆。\n(4)中国少数民族，主要分布于广西壮族自治区～族。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-京"},{"id":"glyph-seal-4ead","script":"seal","character":"亭","reading":"tíng","description":"tíng：(1)有顶无墙，供休息用的建筑物，多建筑在路旁或花园里；凉～。牡丹～。\n(2)建筑得比较简单的小房子书～。邮～。岗～。\n(3)适中，均匀～匀。\n(4)正，当～午（正午，中午）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亭"},{"id":"glyph-seal-4eae","script":"seal","character":"亮","reading":"liàng","description":"liàng：(1)明，有光天～了，敞～。明～。豁～。～光。～度。\n(2)光线屋子里一点～儿也没有。\n(3)明摆出来，显露，显示～相。\n(4)明朗，清楚心里～了。\n(5)声音响洪～。响～。\n(6)使声音响～开嗓子唱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亮"},{"id":"glyph-seal-4eb2","script":"seal","character":"亲","reading":"qīn","description":"我有亲父母。\n亲密。与疏”相对\n王无亲\n⒈父母双～。养～。\n⒉血统最近或夫妻关系的～姐妹。～人。\n⒊婚姻～事。\n⒌有血统或婚姻关系的～戚。～朋。～表姑。\n⒍感情好，关系密切～密。～近。～如一家。\n⒎用嘴唇接触，表示喜爱～一～孩子。\n⒏本身，自己的～自。～身。～眼见到。～笔所写。事必躬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亲"},{"id":"glyph-seal-4eb3","script":"seal","character":"亳","reading":"bó","description":"bó：〔～州〕地名，在安徽省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亳"},{"id":"glyph-seal-4eb5","script":"seal","character":"亵","reading":"xiè","description":"轻慢,轻佻地亲近\n⒈内衣。\n⒉轻慢，亲近且不庄重～渎。\n⒊淫秽，下流行为秽～。猥～","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亵"},{"id":"glyph-seal-4eb6","script":"seal","character":"亶","reading":"dǎn；dàn","description":"dǎn：实在，诚然，信然。\ndàn：古同但”，仅；只。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亶"},{"id":"glyph-seal-4eba","script":"seal","character":"人","reading":"rén","description":"rén：(1)由类人猿进化而成的能制造和使用工具进行劳动、并能运用语言进行交际的动物～类。\n(2)别人，他人～为刀俎，我为鱼肉”。待～热诚。\n(3)人的品质、性情、名誉丢～，文如其～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-人"},{"id":"glyph-seal-4ebf","script":"seal","character":"亿","reading":"yì","description":"安宁;安定\n极多;极大","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亿"},{"id":"glyph-seal-4ec0","script":"seal","character":"什","reading":"shí；shén","description":"shí：(1)十（多用于分数或倍数）～百（十倍和百）。～一（十分之一）。～袭珍藏（形容极其珍重地收藏物品）。\n(2)各种的，各样的～锦（各种各样东西凑成的食品）。～物。\n(3)诗篇篇～。雅～。\nshén：〔～么〕ａ．代词，表示疑问，如～～人？”ｂ．代词，指不确定的事物，如没～～问题”（么”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-什"},{"id":"glyph-seal-4ec1","script":"seal","character":"仁","reading":"rén","description":"rén：(1)一种道德范畴，指人与人相互友爱、互助、同情等～义（ａ．仁爱与正义；ｂ．通情达理，性格温顺，能为别人着想）。～爱。～政。～人志士（仁爱有节操的人）。～义礼智（儒家的伦理思想）。～至义尽。一视同～（同样看待，不分厚薄）。\n(2)果核的最内部分或其他硬壳中可以吃的部分核桃～儿。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仁"},{"id":"glyph-seal-4ec4","script":"seal","character":"仄","reading":"zè","description":"zè：(1)倾斜～立。日～。\n(2)狭窄逼～。\n(3)心里不安歉～。\n〔～声〕古汉语中上声”、去声”、入声”的总称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仄"},{"id":"glyph-seal-4ec5","script":"seal","character":"仅","reading":"jǐn","description":"仅然后得兔。\n⒈只，不过～供参考。她不～自己学习好，还肯辅助同学学习。～ ～一点小事。没必要生气。\n⒉见jǐn。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仅"},{"id":"glyph-seal-4ec6","script":"seal","character":"仆","reading":"pú；pū","description":"pū：向前跌倒～倒。前～后继。\n奴；\n主；\n（僿）\npú：(1)被人雇佣差遣服务的人，与主”相对～人。～从。\n(2)旧谦称我”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仆"},{"id":"glyph-seal-4ec7","script":"seal","character":"仇","reading":"chóu；qiú","description":"chóu：深切的怨恨～敌。～恨。～视。疾恶如～。同～敌忾（全体一致痛恨敌人）。\n恩；\nqiú：(1)古同逑”，匹配。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仇"},{"id":"glyph-seal-4eca","script":"seal","character":"今","reading":"jīn","description":"jīn：现在～天。～生。～世。～番（这次）。古为～用。～是昨非。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-今"},{"id":"glyph-seal-4ecb","script":"seal","character":"介","reading":"jiè","description":"jiè：(1)在两者中间～于两者之间。～词（用在名词、代词之前，合起来表示地点、时间、方向、方式等关系的词，如从”、向”、在”、以”、对于”等）。～入。\n(2)这样，这么像煞有～事（好像真有这么回事似的，多指大模大样，好像有什么了不起）。\n(3)放在心里～意。～怀。\n(4)耿直耿～。\n(5)甲～胄。～壳。\n(6)个（用于人）一～书生。\n(7)大～圭（大玉）。\n(8)传统戏曲脚本里表示情态动作的词笑～。饮酒～。\n(9)助～寿。\n(10)姓。\n(11)古同芥”，芥菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-介"},{"id":"glyph-seal-4ecd","script":"seal","character":"仍","reading":"réng","description":"réng：(1)依然，还，照旧～须努力。～然。～旧。\n(2)因袭，沿袭一～其旧。\n(3)频繁，重复频～。～世（一代又一代，累世）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仍"},{"id":"glyph-seal-4ece","script":"seal","character":"从","reading":"cóng","description":"顺从;依从\n①跟着跟～。\n②顺应；听从～命。\n③从事；参与～军。\n④采取某种方式或态度～宽处理、～略。\n⑤跟随的人随～。\n⑥从属的；次要的主～关系、～犯。\n⑧提示空间和时间的起点～北京到南京、～二月到三月。\n⑨提示经过的地方、处所～门外走过。\n【从长计议】把时间放长些，多加考虑和商量。即不急于作出决定。\n【从犯】我国刑法关于共同犯罪人的一种分类。指在共同犯罪中起次要或辅助作用的人。对于从犯，应当比照主犯从轻、减轻或免除处罚。\n【从谏如流】旧时用以形容君王乐于听取臣属的劝谏，接受其意见。\nfamousnovel是个定语从句，由who引导，修饰man。\n【从军】参军；当兵。\n【从良】指妓女不再卖身而嫁人。\n【从容】\n①镇定，不慌乱举止～。\n②宽裕时间～。\n【从容不迫】不慌不忙，镇定自若。\n【从容自如】不慌不忙，神态沉着自然。\n【从善如流】形容能很快地听取好意见或善意的规劝。\n【从属关系】两个概念之间一个概念的外延包含另一个概念全部外延的关系。如'工业'与'轻工业'。\n【从征】随军出征。\n从zōng 1.后多作\"踪\"。踪迹。\n从sǒng 1.通\"耸\"。 2.通\"怂\"。参见\"从容\"﹑\"从谀\"。\n从zòng 1.直。南北曰从，东西曰横。 2.合纵。 3.放纵。 4.纵然。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-从"},{"id":"glyph-seal-4ed1","script":"seal","character":"仑","reading":"lún","description":"自我反省检讨\n见昆仑”\n⒈条理，次序。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仑"},{"id":"glyph-seal-4ed3","script":"seal","character":"仓","reading":"cāng","description":"泛指储藏物资的建筑物\n①收藏谷物的建筑物粮～。\n②姓。\n【仓猝】\n【仓卒】\n【仓促】匆忙时间～。\n【仓皇】\n【仓黄】匆忙而带着慌张～逃离现场。又作苍黄。\n【仓颉】一作苍颉。传说是汉字的创造者，黄帝的史官。可能是古代整理文字的代表人物之一。\n【仓库】专供储存物资的建筑物。\n【仓廪】储存粮食的仓库。\n仓chuàng 1.悲伤。参见\"仓兄\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仓"},{"id":"glyph-seal-4ed4","script":"seal","character":"仔","reading":"zǎi；zī；zǐ","description":"zī：〔～肩〕所担负的职务。\nzǐ：幼小的（多指家畜）～鸡。～猪。\n〔～细〕周密，细致，如办事～～”。\nzǎi：同崽”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仔"},{"id":"glyph-seal-4ed5","script":"seal","character":"仕","reading":"shì","description":"shì：(1)做官出～。～宦。学而优则～。～途。～女（a.宫女，贵族妇女；b.以社会上层妇女为题材的中国画。均亦作士女”）。\n(2)审察弗问弗～”。\n(3)古同事”，事业。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仕"},{"id":"glyph-seal-4ed6","script":"seal","character":"他","reading":"tā","description":"tā：(1)称你、我以外的第三人，一般指男性，有时泛指，不分性别～们（可包括男性和女性）。～杀。\n(2)别的，另外的～人。～日。～乡。～山之石，可以攻玉。其～。\n(3)虚指睡～一觉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-他"},{"id":"glyph-seal-4ed8","script":"seal","character":"付","reading":"fù","description":"fù：(1)交，给支～。托～。～款。～梓（把稿件交付刊印）。～讫。～出。～与。～之一笑。～诸东流。\n(2)量词，指中药（亦作服”）一～药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-付"},{"id":"glyph-seal-4ed9","script":"seal","character":"仙","reading":"xiān","description":"xiān：(1)神话中称有特殊能力、可以长生不死的人～人。～女。～子。～界。～境（a.仙人居住的地方；b.形容景物美好的地方）。～风道骨。～山琼阁（喻虚无缥缈的美妙幻景）。\n(2)具有高超才能的人诗～。酒～。\n(3)婉称死～去。～逝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仙"},{"id":"glyph-seal-4ede","script":"seal","character":"仞","reading":"rèn","description":"rèn：(1)古代计量单位一～（周尺八尺或七尺。周尺一尺约合二十三厘米）。山高万～。\n(2)测量深度。\n(3)古同韧”，坚韧。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仞"},{"id":"glyph-seal-4ee1","script":"seal","character":"仡","reading":"yì；gē","description":"yì：勇猛雄壮的样子～～（a.壮勇。b.高大）。～然。～栗（迅速的样子）。\ngē：〔～佬族〕中国少数民族，主要分布于贵州省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仡"},{"id":"glyph-seal-4ee3","script":"seal","character":"代","reading":"dài","description":"dài：(1)替～替。～办。～销。～序。～表。\n(2)历史上划分的时期时～。世～。古～。近～。现～。当（dāng）～。年～。\n(3)世系的辈分下一～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-代"},{"id":"glyph-seal-4ee4","script":"seal","character":"令","reading":"lìng；líng；lǐng","description":"líng：〔～狐〕ａ．古地名，在今山西省临猗县一带；ｂ．复姓。\nlǐng：量词，印刷用的原张平版纸五百张为一令。\nlìng：(1)上级对下级的指示命～。法～。朝（zhāo）～夕改。\n(2)古代官名县～。～尹。尚书～。\n(3)使，使得～人兴奋。\n(4)时节时～。节～。\n(5)美好，善～名。～辰。～闻（好名声）。\n(6)敬辞，用于对方的亲属或有关系的人～尊。～堂。～岳。～郎。～爱。\n(7)短的词调（diào），散曲中不成套的曲（多用于词调、曲调名）小～。如梦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-令"},{"id":"glyph-seal-4ee5","script":"seal","character":"以","reading":"yǐ","description":"yǐ：(1)用，拿，把，将～一当十。～苦为乐。～身作则。～邻为壑。～讹传讹。～往鉴来。\n(2)依然，顺，按照～时启闭。物～类聚。\n(3)因为～人废言。勿～善小而不为。不～物喜，不～己悲。\n(4)在，于（指时日）子厚～元和十四年十一月八日卒，年四十七”。\n(5)目的在于～待时机。～儆效尤。\n(6)文言连词，与而”用法相同梦寐～求。\n(7)用在方位词前，表明时间、方位、方向或数量的界限～前。～内。\n(8)用在动词后，类似词的后缀可～。得～。\n(9)古同已”，已经。\n(10)太，甚不～急乎？\n(11)及，连及富～其邻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-以"},{"id":"glyph-seal-4eea","script":"seal","character":"仪","reading":"yí","description":"法度;礼法\n置此以为法,立此以为仪,将以量度天下之王公大人、卿\n⒈容貌，举止～容。～态。～表。\n⒉按程序进行的礼节～式。司～。\n⒊礼物贺～。谢～。\n⒋准则，法度～则。\n⒌指仪器，供测绘、实验等用的有一定准则的用具经纬～。浑天～。地震～。教学～器。\n⒍〈古〉通\"宜\"。应该。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仪"},{"id":"glyph-seal-4ef0","script":"seal","character":"仰","reading":"yǎng；áng","description":"yǎng：(1)脸向上，与俯”相对～首。～望。\n(2)敬慕久～。敬～。\n(3)依赖～承。～赖。～仗。～人鼻息。\n(4)旧时公文用语。上行文中用在请、祈、恳”等字之前，表示恭敬；下行文中表示命令～即尊照。\n(5)服下，指服毒～药（服毒药自杀）。～毒。\n(6)姓。\n俯；\náng：古同昂”，情绪高。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仰"},{"id":"glyph-seal-4ef2","script":"seal","character":"仲","reading":"zhòng","description":"zhòng：(1)兄弟排行次序二～兄。～弟。\n(2)在当中的～春（春季的第二个月，即农历二月。仲夏、仲秋、仲冬依此类推）。～裁（居间调停、裁判）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仲"},{"id":"glyph-seal-4ef6","script":"seal","character":"件","reading":"jiàn","description":"jiàn：(1)量词，用于个体事物一～事。\n(2)指可以一一计算的事物零～儿。案～。\n(3)不平常的大事情事～。\n(4)文书证明之类文～。来～。证～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-件"},{"id":"glyph-seal-4ef7","script":"seal","character":"价","reading":"jià；jiè","description":"jiè：旧时称派遣传递东西或传达事情的人走～驰书来诣”。\n（價）\njie：(1)方言，用在否定副词后面加强语气不～。\n(2)副词性词尾震天～响。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-价"},{"id":"glyph-seal-4efb","script":"seal","character":"任","reading":"rèn；rén","description":"rèn：(1)相信，信赖信～。\n(2)使用，给予职务～命。～人唯贤。\n(3)负担，担当担～。～课。\n(4)职务就～。到～。～重道远。\n(5)由着，听凭～凭。～性。～意。～从。～随。听～。放～自流。听之～之。\n(6)不论，无论～何。～人皆知。\n免；\nrén：(1)中国古代女子爵位名。\n(2)中国古代南方的一种民族乐曲。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-任"},{"id":"glyph-seal-4efd","script":"seal","character":"份","reading":"fèn；bīn","description":"fèn：(1)整体里的一部～额。～饭。股～。\n(2)量词指成组、成件的一～儿报纸。\n(3)用在省、县、年、月”后面，表示划分的单位省～。月～。\nbīn：古同彬”，文质兼备。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-份"},{"id":"glyph-seal-4eff","script":"seal","character":"仿","reading":"fǎng","description":"fǎng：(1)效法，照样做～效。～古。～冒。～宋（印刷字体的一种，亦称仿宋体”）。\n(2)依照范本写的字～影。～书。\n(3)相似，好像～像（仿佛相似）。～佛（fú）。二者相～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仿"},{"id":"glyph-seal-4f01","script":"seal","character":"企","reading":"qǐ","description":"qǐ：(1)踮着脚看，今用为盼望的意思～盼。～足而待。～及（盼望达到，希望赶上）。～图（图谋）。\n(2)开启。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-企"},{"id":"glyph-seal-4f09","script":"seal","character":"伉","reading":"kàng","description":"kàng：(1)对等、相称～俪（指配偶、夫妇）。～礼。\n(2)正直、刚直～直。～行（xíng）（高尚的行为）。\n(3)古同抗”，对等。\n(4)古同闶”，高大。\n(5)骄纵，傲慢太子轻而庶子～”。～厉（高傲，凌厉）。\n(6)强健～健。\n(7)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伉"},{"id":"glyph-seal-4f0a","script":"seal","character":"伊","reading":"yī","description":"yī：(1)彼，他，她～说。～人（那个人，多指女性）。\n(2)文言助词下车～始。～谁之力？～于胡底（到什么地步为止，不堪设想的意思）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伊"},{"id":"glyph-seal-4f0d","script":"seal","character":"伍","reading":"wǔ","description":"wǔ：(1)古代军队的编制一～（五人）。\n(2)军队入～。落～（掉队）。\n(3)同伴的人羞与为～。\n(4)五”的大写。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伍"},{"id":"glyph-seal-4f0e","script":"seal","character":"伎","reading":"jì；qí","description":"jì：(1)技巧，才能～痒（人擅长某种技艺，一遇机会，急欲表现，好像皮肤发痒不能自忍，亦作技痒”）。～俩（liǎng）。\n(2)古代称以歌舞为业的女子。\nqí：〔～～〕奔走的样子，如鹿斯之奔，惟足～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伎"},{"id":"glyph-seal-4f0f","script":"seal","character":"伏","reading":"fú","description":"fú：(1)趴，脸向下，体前屈～卧。～案读书。\n(2)低下去此起彼～。\n(3)屈服，承认错误或受到惩罚～法。～输。～辩（伏罪的供状，亦作伏辨”）。\n(4)使屈服降～。降龙～虎。\n(5)隐藏～兵。埋～。\n(6)农历划分夏季最炎热的三个阶段～日。～旱。～暑。～天。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伏"},{"id":"glyph-seal-4f10","script":"seal","character":"伐","reading":"fá","description":"fá：(1)砍～树。砍～。\n(2)征讨讨～。～罪（征讨有罪的人）。口诛笔～。\n(3)自夸～善（夸自己的好处）。～智。不矜不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伐"},{"id":"glyph-seal-4f11","script":"seal","character":"休","reading":"xiū；xù","description":"xiū：(1)歇息～整。～假。～闲。离～。\n(2)停止～业。\n(3)完结（多指失败或死亡）。\n(4)旧指丈夫把妻子赶回母家，断绝夫妻关系～妻。\n(5)不要～想。～提。\n(6)吉庆，美善，福禄～咎（吉凶）。\n(7)助词，用于语末，与罢”、了”等用法相当归～。\n(8)辞去官职～官。\n戚；\nxù：古同煦”，温暖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-休"},{"id":"glyph-seal-4f17","script":"seal","character":"众","reading":"zhòng","description":"⒈多，许多～多。～人。～星捧月。\n⒉许多人群～。～怒难犯。～望所归。～志成城。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-众"},{"id":"glyph-seal-4f18","script":"seal","character":"优","reading":"yōu","description":"⒈美好。跟\"劣\"相对～等品。～美别致。～秀教师。～良品质。\n①从容。\n②犹豫不决～柔寡断。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-优"},{"id":"glyph-seal-4f19","script":"seal","character":"伙","reading":"huǒ","description":"同火”。古兵制十人为火,同火的人互称火伴。俗作伙伴,同伴\n合伙;由若干人结成的一群\n群聚;结伴;联合一起干\n一群的人\n伙〈名〉\n伙食。饭食\n⒉联合，共同～办工厂。～同一起∠～经商。\n⒊量词。群一～小孩。五人一～。\n⒋集体所办的餐食起～。搭～。～食团。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伙"},{"id":"glyph-seal-4f1a","script":"seal","character":"会","reading":"huì","description":"⒈聚合，联合～合。聚～。～师。～盟。宴～。\n⒉见面，对话～见。～面。～客。～话。\n⒊理解，懂得～意。能领～。\n⒋能，可能，善于共产主义一定～实现。他～开飞机。不～不懂吧！她能说～道。\n⒌时机机～。逢时遇～。适逢其～。\n⒍短促的时间这～儿。一～儿就来。请等～儿吧。\n⒎付钱～账。茶钱我～过了。\n⒏多数人的集合，或为共同目的所组成的团体纪念～。报告～。商～。学生～。董事～。人民代表大～。\n⒑恰巧，正好～天大雨，道不通。\n⒒见kuài。\n⒈总计。\n①管理与计算财务的工作。\n②担任会计工作的人。。\n会kuò 1.见\"会撮\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-会"},{"id":"glyph-seal-4f1b","script":"seal","character":"伛","reading":"yǔ","description":"弯腰","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伛"},{"id":"glyph-seal-4f1f","script":"seal","character":"伟","reading":"wěi","description":"奇异","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伟"},{"id":"glyph-seal-4f20","script":"seal","character":"传","reading":"chuán；zhuàn","description":"chuán：传递、传播、传授。zhuàn：记述人物生平事迹的文字；某些叙事作品的名称，如传记。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-4f24","script":"seal","character":"伤","reading":"shāng","description":"⒈受到损害、损坏受～。枪～。重～。\n⒉损害，妨碍～害。损～。～点皮肉。无～大局。\n⒊遭受某种致病因素而得病～风。～暑。\n⒋悲哀～心。悲～。\n⒌使用过度以致厌烦这种菜吃～了。\n⒍得罪，诋毁有意中～。出口～人。\n①伤寒杆菌引起的急性传染病。\n②中医学上泛指各种热病或风寒引起的疾病。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伤"},{"id":"glyph-seal-4f25","script":"seal","character":"伥","reading":"chāng","description":"迷信传说中的被老虎咬死的人变成的鬼,这种鬼引导老虎咬别的人\n旧指为盗贼察情探路的人。也指助纣为虐的恶人\n无所适从。又称伥伥\n伥鬼","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伥"},{"id":"glyph-seal-4f26","script":"seal","character":"伦","reading":"lún","description":"条理,顺序\n人伦,人与人之间的道德关系\n⒈类，同类不～不类。超群绝～。\n⒉条理，顺序语无～次。\n⒊比，匹敌～比。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伦"},{"id":"glyph-seal-4f2a","script":"seal","character":"伪","reading":"wěi","description":"人为;矫饰\n伪装;假装\n⒈假，不真实～装。～科学。～劣产品。去～存真。\n⒉诡诈，不诚实奸～。虚～。\n⒊非法的窃取政权而不为人民承认的～总统。～政府。\n伪é 1.通\"讹\"。改变;变化。 2.通\"讹\"。错误;差错。参见\"伪谬\"。 3.通\"吪\"。动。\n伪guì 1.钱币。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伪"},{"id":"glyph-seal-4f2b","script":"seal","character":"伫","reading":"zhù","description":"zhù：长时间地站着～立。～候。～听。～思（久望而辗转思念）。～结（思念之情，积集于心）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伫"},{"id":"glyph-seal-4f2f","script":"seal","character":"伯","reading":"bó；bǎi；bà","description":"bó：(1)兄弟排行次序～仲（指兄弟的次第，喻事物不相上下）。\n(2)父亲的哥哥～～。～父。～母。\n(3)对父辈戚友的尊称老～。世～。\n(4)封建制度五等爵位的第三等～爵。\n(5)旧时对文章、道德足为表率者的尊称海内文章～”。\n(6)姓。\nbǎi：〔大～子〕丈夫的大哥。\nbà：古同霸”，古代诸侯联盟的首领。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伯"},{"id":"glyph-seal-4f34","script":"seal","character":"伴","reading":"bàn","description":"bàn：(1)同在一起而能互助的人伙～。～侣。\n(2)陪同～随。陪～。～和（hè）。～舞。～奏。～读（古代官名，中国宋代有南北院伴读，负责宗室子弟的教学，辽、金至明代，皆为亲王府官）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伴"},{"id":"glyph-seal-4f36","script":"seal","character":"伶","reading":"líng","description":"líng：旧时称以演戏为职业的人优～。名～。～官（古代乐官）。\n〔～仃〕孤独。\n〔～俐〕聪明；灵活。\n〔～俜〕孤独的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伶"},{"id":"glyph-seal-4f38","script":"seal","character":"伸","reading":"shēn","description":"shēn：(1)舒展开～直。～手（ａ．伸出手；ｂ．喻向别人或上级要东西、荣誉、照顾；ｃ．指插手）。～张（扩大，如～张正义”）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伸"},{"id":"glyph-seal-4f3a","script":"seal","character":"伺","reading":"sì；cì","description":"sì：观察，侦候窥～。～机。～察。～应（yìng）（等候响应）。\ncì：〔～候〕ａ．在人身边供使唤；ｂ．照料饮食起居（候”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伺"},{"id":"glyph-seal-4f3c","script":"seal","character":"似","reading":"sì；shì","description":"sì：(1)相类，像相（xiāng）～。类～。～是而非。\n(2)好像，表示不确定～乎。～应如此。\n(3)表示比较，有超过的意思一个高～一个。\nshì：〔～的〕跟某种情况或事物相似，如他乐得什么～～”。亦作是的”（的”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-似"},{"id":"glyph-seal-4f43","script":"seal","character":"佃","reading":"diàn；tián","description":"diàn：向地主或官府租种土地的农民～户。～农。～客（晋代世家豪强荫庇下的一种依附农民）。～东。\ntián：(1)耕作。\n(2)古同畋”，打猎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佃"},{"id":"glyph-seal-4f46","script":"seal","character":"但","reading":"dàn","description":"dàn：(1)只，仅，只是～愿如此。～凡（凡是，只要是）。～分（只要）。\n(2)不过，可是工作虽辛苦，～没有叫苦的。\n(3)徒然何～远走，亡匿于幕北苦寒无水草之地为？”\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-但"},{"id":"glyph-seal-4f4d","script":"seal","character":"位","reading":"wèi","description":"wèi：(1)所处的地方座～。部～。～置（ａ．所在或所占的地方；ｂ．地位）。～于。\n(2)职务的高低地～。职～。名～。\n(3)特指君主的地位即～。篡～。\n(4)一个数中每个数码所占的位置个～。百～数。\n(5)量词，常用于人，表尊重诸～。各～。几～客人。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-位"},{"id":"glyph-seal-4f4e","script":"seal","character":"低","reading":"dī","description":"dī：(1)地势或位置在一般标准或平均程度之下，与高”相对～空。～地。～谷。～潮。～沉（ａ．云层厚而低；ｂ．声音低；ｃ．情绪低落）。\n(2)矮短身材～矮。\n(3)细小，沉重～微（ａ．声音细小；ｂ．身份或地位低）。～吟。\n(4)程度差～级。～能。眼高手～。\n(5)卑贱～贱。～首下心。\n(6)等级在下的～俗。～档商品。\n(7)价钱少～价出售。\n(8)俯，头向下垂～头从事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-低"},{"id":"glyph-seal-4f50","script":"seal","character":"佐","reading":"zuǒ","description":"zuǒ：(1)辅助，帮助～证（证据）。～餐。\n(2)处于辅助地位的人僚～。\n(3)劝～食。～酒（ａ．陪伴喝酒；ｂ．就着菜肴把酒喝下去）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佐"},{"id":"glyph-seal-4f53","script":"seal","character":"体","reading":"tǐ","description":"⒈人或动物的全身人～。机～。身～。～重。～温。\n⒊事物的本身或全部物～。全～。个～。整～。总～。\n⒋形态气～。立～。\n⒌形式，规格字～。得～。\n⒍文章的体裁骚～。骈文～。古诗～。\n⒎实质，根本，主要的实～。本～。主～。\n⒏指体制国～。政～。\n①身分有失～面。\n②光荣，光彩显得～面。\n③漂亮，好看她穿着很～面。\n①家庭成员个人积蓄的财物。\n②私下的，亲近的～己话。\n体bèn 1.见\"体夫\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-体"},{"id":"glyph-seal-4f55","script":"seal","character":"何","reading":"hé；hē；hè","description":"hé：(1)疑问代词（ａ．什么，如～人？”ｂ．为什么，如～必如此？”ｃ．哪样，怎样，如～不？”～如？”ｄ．哪里，如～往？”ｅ．发表反问，如～乐而不为？”）。\n(2)副词，多么～其壮哉！\n(3)姓。\nhē：古同呵”，谴责。\nhè：古同荷”，担。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-何"},{"id":"glyph-seal-4f57","script":"seal","character":"佗","reading":"tuó","description":"tuó：负荷以一马自～负三十日食”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佗"},{"id":"glyph-seal-4f59","script":"seal","character":"余","reading":"yú","description":"饱足。足食得饱\n剩下;剩余\n剩下的,多余的\n残留的;\n⒈我，我的。\n⒉剩下的，多出的剩～。节～。多～。有～。～粮。不遗～力。\n⒊遗留，遗存城荒古迹～。\n⒋零数十～天。百～人。五里～。\n⒌后，以外业～。工作之～。\n余yù 1.姓。见\"余且\"。\n余xú 1.见\"余吾\"。\n余tú 1.梼余，山名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-余"},{"id":"glyph-seal-4f5a","script":"seal","character":"佚","reading":"yì；dié","description":"yì：(1)同逸”②③。\n(2)放荡淫～。～游。\n(3)美～女。\n(4)姓。\ndié：古同迭”，轮流，更替。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佚"},{"id":"glyph-seal-4f5b","script":"seal","character":"佛","reading":"fó；fú；bì；bó","description":"fó：(1)梵语佛陀”，是对佛教创始人释迦牟尼的简称，亦是佛教徒对修行圆满的人的称呼～爷。～像。借花献～。\n(2)指佛教”（世界主要宗教之一）～家。～寺。～老。～经。～龛。～事（佛教徒诵经、祈祷及供奉佛像等活动）。\nfú：古同拂”，违背，违反。\n〔仿～〕见仿”。\nbì：古同弼”，辅弼。\nbó：古同勃”，兴起。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佛"},{"id":"glyph-seal-4f5c","script":"seal","character":"作","reading":"zuò","description":"zuò：(1)起，兴起，现在起振～。枪声大～。\n(2)从事，做工工～。～息。～业。\n(3)举行，进行～别（分别）。～乱。～案。～战。～报告。\n(4)干出，做出，表现出，制造出～恶（è）。～弊。～梗。～祟。～态。～色。～为。～难。～奸犯科（为非作歹，触犯法令）。\n(5)当成，充当～罢。～保。～伐（做媒人）。～壁上观（人家交战，自己站在营垒上看，喻坐观别人成败）。\n(6)创造创～。写～。～曲。～者。\n(7)文艺方面的成品～品。不朽之～。\n(8)同做”。\n(9)旧时手工业制造加工的场所～坊。\n(10)从事某种活动～揖。～弄。～死。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-作"},{"id":"glyph-seal-4f5d","script":"seal","character":"佝","reading":"gōu；kòu","description":"gōu：〔～偻〕由于缺乏维生素Ｄ引起钙、磷代谢障碍导致的骨骼发育不良。俗称小儿软骨病”。\nkòu：〔～瞀〕昏味无知。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佝"},{"id":"glyph-seal-4f5e","script":"seal","character":"佞","reading":"nìng","description":"nìng：(1)有才智，旧时谦称不～。\n(2)善辩，巧言谄媚～人（有口才而不正派的人）。～幸（以谄媚而得宠幸）。～史（为讨好当权者而歪曲篡改事实的历史）。～臣。奸～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佞"},{"id":"glyph-seal-4f60","script":"seal","character":"你","reading":"nǐ","description":"nǐ：(1)称对方，多称指一个人，有时也指称若干人～厂。～方。\n(2)泛指任何人～死我活。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-你"},{"id":"glyph-seal-4f63","script":"seal","character":"佣","reading":"yòng","description":"佣者笑而应。\n若为佣耕。\n子不佣矣。\n佣chōng 1.均;公平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佣"},{"id":"glyph-seal-4f65","script":"seal","character":"佥","reading":"qiān","description":"众人;大家\n连枷,打谷的农具\n用同签”。签署\n⒈都，皆～同。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佥"},{"id":"glyph-seal-4f69","script":"seal","character":"佩","reading":"pèi","description":"pèi：(1)挂，带～带。～戴。～剑。\n(2)古代系在衣带上的玉饰玉～。\n(3)心悦诚服～服。钦～。敬～。可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佩"},{"id":"glyph-seal-4f70","script":"seal","character":"佰","reading":"bǎi","description":"bǎi：百”的大写。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佰"},{"id":"glyph-seal-4f73","script":"seal","character":"佳","reading":"jiā","description":"jiā：美，好的～美。～妙。～句。～作。～音。～节。～境。～期。～人。～丽（ａ．美丽；ｂ．美女）。～偶。～酿。美酒～肴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佳"},{"id":"glyph-seal-4f76","script":"seal","character":"佶","reading":"jí","description":"jí：(1)健壮。\n(2)正。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佶"},{"id":"glyph-seal-4f7b","script":"seal","character":"佻","reading":"tiāo","description":"tiāo：(1)轻薄，不庄重轻～。～薄。～巧（ａ．轻佻巧诈；ｂ．文辞细巧而不严肃）。\n(2)窃取，偷～天之功以为己力”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佻"},{"id":"glyph-seal-4f7c","script":"seal","character":"佼","reading":"jiǎo","description":"jiǎo：美好～～。～人（美人）。～好。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佼"},{"id":"glyph-seal-4f7e","script":"seal","character":"佾","reading":"yì","description":"yì：古代乐舞的行列八～（八行八列，共六十四人）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佾"},{"id":"glyph-seal-4f7f","script":"seal","character":"使","reading":"shǐ","description":"shǐ：(1)用～用。～劲。～役。～力。～钱。\n(2)派，差谴～唤。～命。～女。\n(3)让，令，叫迫～。\n(4)假若假～。即～。\n(5)奉命办事的人～者。大～。公～。～馆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-使"},{"id":"glyph-seal-4f83","script":"seal","character":"侃","reading":"kǎn","description":"kǎn：〔～～〕理直气壮，从容不迫的样子，如～～而谈”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侃"},{"id":"glyph-seal-4f88","script":"seal","character":"侈","reading":"chǐ","description":"chǐ：(1)浪费，用财物过度～糜。奢～。穷奢极～。\n(2)夸大～谈。\n(3)邪行放辟邪～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侈"},{"id":"glyph-seal-4f89","script":"seal","character":"侉","reading":"kuǎ","description":"kuǎ：口音与本地语音不合他说话有点儿～。～子（蔑视语）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侉"},{"id":"glyph-seal-4f8b","script":"seal","character":"例","reading":"lì","description":"lì：(1)可以做依据的事物～证。～题。举～。～句。～如。\n(2)规定～外（不按规定的，和一般情况不同的）。体～。凡～。条～。破～。发凡起～。\n(3)按规定的，照成规进行的～会。～假。～行公事。\n(4)调查或统计时指合于某种条件的具有代表性的事情事～。病～。案～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-例"},{"id":"glyph-seal-4f8d","script":"seal","character":"侍","reading":"shì","description":"shì：伺候，在旁边陪着服～。～立。～者（侍奉左右的人）。～从。～读（给帝王讲学的人）。～坐。～役（仆人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侍"},{"id":"glyph-seal-4f91","script":"seal","character":"侑","reading":"yòu","description":"yòu：(1)相助。\n(2)在筵席旁助兴，劝人吃喝～食。～饮。～觞。\n(3)报答。\n(4)古同宥”，宽赦。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侑"},{"id":"glyph-seal-4f94","script":"seal","character":"侔","reading":"móu","description":"móu：相等，齐相～。～色揣称（chèn）（写文章摹绘物色恰到好处）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侔"},{"id":"glyph-seal-4f97","script":"seal","character":"侗","reading":"dòng；tóng；tǒng","description":"dòng：(1)中国少数民族，主要分布于贵州、湖南等省和广西壮族自治区～族。～剧。\n(2)诚实的样子。\n〔～胴〕形状。\ntóng：幼稚，无知。\ntǒng：同统”③。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侗"},{"id":"glyph-seal-4f9b","script":"seal","character":"供","reading":"gòng；gōng","description":"gōng：准备着东西给需要的人应用～给（jǐ）。～求。～应。～需。～销。提～。～不应求。\n求；\ngòng：(1)奉献～养。～献。～奉。～佛。～职。\n(2)祭祀用的东西～桌。～品。～果。上～。\n(3)被审问时在法庭上述说事实招～。口～。～状。～认。～词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-供"},{"id":"glyph-seal-4f9d","script":"seal","character":"依","reading":"yī","description":"yī：(1)靠，仗赖～靠。～傍（a.依靠；b.摹仿，多指艺术、学问）。～恋。～偎。～存。～附。归～。\n(2)按照～照。～旧。～据。～次。\n(3)顺从，答应～从。～顺。～允。\n(4)亲密的样子有～其士”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-依"},{"id":"glyph-seal-4fa0","script":"seal","character":"侠","reading":"xiá","description":"侠客\n材力绝人,少重然许,喜侠节。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侠"},{"id":"glyph-seal-4fa3","script":"seal","character":"侣","reading":"lǚ；lv","description":"lǚ：(1)伴～伴。伴～。爱～。情～。旧～。\n(2)结为伴侣～鱼虾而友麋鹿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侣"},{"id":"glyph-seal-4fa5","script":"seal","character":"侥","reading":"yáo；jiao","description":"贪求不止\n引申指希求意外成功或幸免\n侥薄,即浇薄。指民俗浮薄\n僥侥\n南方有焦侥人,长三尺,短之极,从人,尧声。╠","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侥"},{"id":"glyph-seal-4fa6","script":"seal","character":"侦","reading":"zhēn","description":"问,卜问。凭借占卜来寻求预言\n侦察\n探子;间谍\n侦zhēn探伺，暗中察看～探。～察。～查。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侦"},{"id":"glyph-seal-4fa7","script":"seal","character":"侧","reading":"cè","description":"边缘\n向旁边歪斜\n侧弁之俄\n①旁边～面、两～。\n②向一边歪斜～目、～耳细听、～重效果。又见zè。\n【侧锋】〈美〉中国画技法。运笔时笔头向左右倾斜，使笔尖、笔腰、笔根同时发挥作用。兼有粗、细、浓、淡、干、湿等变化。常用于中国画的意笔画。又称偏锋。\n【侧棱】棱柱或棱台的两个侧面的公共边。\n【侧面】\n【侧面积】侧面的面积。\n【侧目】不敢正视，斜着眼睛看。形容害怕而又愤恨～而视。\n【侧线】〈生〉动物身体两侧，排列成直线形的一种构造。某些蛔虫的侧线由外胚层所形成，排泄管由此通过。鱼类及水生两栖类动物的侧线能感觉水流振动及声音。\n【侧芽】生在叶腋、尚未发育成长的枝或花的雏体。又叫腋芽。\n【侧泳】一种游泳姿势。游时侧卧水面，两手臂轮流划水。\n【侧足】、形容因畏惧而不敢对面站立～而立。\n②置足；落脚。\n⒈［侧声］即\"仄声\"，见 \"仄\n厕同。\" 8.藏伏。 9.轻微。 10.汉字笔画中\"点\"的古称。参见\"永字八法\"。 11.通\"恻\"。悲伤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侧"},{"id":"glyph-seal-4fa8","script":"seal","character":"侨","reading":"qiáo","description":"客居异地\n客居国外\n寄居国外的人\n⒈寄居在国外或外乡～居。～寓。\n⒉寄居在国外的人～民。华～。外～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侨"},{"id":"glyph-seal-4fa9","script":"seal","character":"侩","reading":"kuài","description":"牙侩。两伙人之间的中间人或代理人等\n撮合。说合买卖之间的价钱以成交","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侩"},{"id":"glyph-seal-4faa","script":"seal","character":"侪","reading":"chái","description":"一起\n⒉共同，一起长幼～居。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侪"},{"id":"glyph-seal-4fae","script":"seal","character":"侮","reading":"wǔ","description":"wǔ：(1)欺负，轻慢～辱（使对方人格或名誉受到损害，蒙受耻辱）。～蔑（轻视，轻蔑）。欺～。不可～。\n(2)古代奴婢的贱称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侮"},{"id":"glyph-seal-4faf","script":"seal","character":"侯","reading":"hòu；hóu","description":"hóu：(1)封建制度五等爵位的第二等～爵。～门。公～。封～。诸～。\n(2)古代用作士大夫之间的尊称。\n(3)姓。\nhòu：〔闽～〕地名，在中国福建省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侯"},{"id":"glyph-seal-4fb5","script":"seal","character":"侵","reading":"qīn","description":"qīn：(1)（敌人）进入境内，（外来的或有害的事物）进入内部～害。～吞。～略。～染。～蚀。\n(2)渐近～晨。～晓。～早（破晓，天刚亮）。\n(3)古代称荒年五谷不生，谓之大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侵"},{"id":"glyph-seal-4fbf","script":"seal","character":"便","reading":"biàn；pián","description":"biàn：(1)顺利，没有困难或阻碍～当。～利。～道。～民。\n(2)简单的，礼节上非正式的～宴。～衣。～函（形式比较简便的信件）。简～。～宜。随～（适当地，看事实需要而自行处理事情）。\n(3)便利的时候～中请来信。\n(4)就说了～做。\n(5)排泄屎尿或排泄出来的屎尿大～。～秘。\n即；就；\npián：〔～～〕肚子肥大的样子，如大腹～～”。\n〔～嬖〕封建统治者所亲近宠爱的人。\n〔～佞〕善于用花言巧语讨好的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-便"},{"id":"glyph-seal-4fc3","script":"seal","character":"促","reading":"cù","description":"cù：(1)近，时间紧迫～膝。～席（坐近）。急～。短～。仓～。\n(2)催，推动～使。～进。敦～。督～。催～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-促"},{"id":"glyph-seal-4fc4","script":"seal","character":"俄","reading":"é","description":"é：短时间～尔。～然。～顷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俄"},{"id":"glyph-seal-4fc5","script":"seal","character":"俅","reading":"qiú","description":"qiú：〔～～〕恭顺的样子。\n〔～人〕中国少数民族独龙族的旧称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俅"},{"id":"glyph-seal-4fca","script":"seal","character":"俊","reading":"jùn","description":"jùn：(1)才智出众的人～杰。～伟。～彦（才智杰出的人）。～爽。～造（学识造诣很深的人）。\n(2)容貌美丽～俏。～美。～秀。～逸（俊美洒脱，不同凡俗）。英～。\n(3)古同峻”，大。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俊"},{"id":"glyph-seal-4fce","script":"seal","character":"俎","reading":"zǔ","description":"zǔ：(1)古代祭祀时放祭品的器物～豆（a.俎”和豆”，都是古代祭祀用的器具；b.祭祀，崇奉）。\n(2)切肉或切菜时垫在下面的砧板刀～（刀和砧板）。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俎"},{"id":"glyph-seal-4fd1","script":"seal","character":"俑","reading":"yǒng","description":"yǒng：古代殡葬用的木制或陶制的偶人木～。陶～。女～。兵马～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俑"},{"id":"glyph-seal-4fd7","script":"seal","character":"俗","reading":"sú","description":"sú：(1)社会上长期形成的风尚、礼节、习惯等～尚。风～。习～。约定～成（指某种事物是由群众通过长期实践而认定形成）。\n(2)大众化的，最通行的，习见的～名。～语。～曲。雅～共赏。\n(3)趣味不高的，令人讨厌的～气。～物。鄙～。粗～。庸～。\n(4)凡世间，相对于仙佛僧道～人。世～。僧～。凡夫～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俗"},{"id":"glyph-seal-4fd8","script":"seal","character":"俘","reading":"fú","description":"fú：(1)打仗时被擒的敌人～虏。战～。遣～。\n(2)打仗时擒住敌人～获。被～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俘"},{"id":"glyph-seal-4fda","script":"seal","character":"俚","reading":"lǐ","description":"lǐ：民间的，通俗的～俗（粗俗）。～语。～歌。～曲。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俚"},{"id":"glyph-seal-4fdd","script":"seal","character":"保","reading":"bǎo","description":"bǎo：(1)看守住，护着不让受损害或丧失～卫。～管。～健。～障。～密。明哲～身。朝不～夕（早晨保不住晚上会发生什么情况。形容形势危急）。\n(2)维持原状，使不消失或减弱～持。～洁。～质。～墒。\n(3)负责～证。～荐。～修。～险。确～。担～。\n(4)旧时户口的一种编制，若干甲为一保。\n(5)旧称佣工酒～（酒店服务人员）。佣～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-保"},{"id":"glyph-seal-4fde","script":"seal","character":"俞","reading":"yú；yù；shù","description":"yú：(1)文言叹词，表示允许～允（原指帝王允许臣下的请求，后在一般书信中用作请对方允许的敬辞）。\n(2)安古圣人不以感私伤神，～然而以待耳”。\n(3)姓。\nyù：(1)古同愈”，更加。\n(2)病愈。\nshù：同腧”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俞"},{"id":"glyph-seal-4fdf","script":"seal","character":"俟","reading":"sì；qí","description":"sì：等待～机进攻。\n〔～次〕依次。\nqí：〔万（mò）～〕见万2”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俟"},{"id":"glyph-seal-4fe1","script":"seal","character":"信","reading":"xìn；shēn","description":"xìn：(1)诚实，不欺骗～用。～守。～物。～货。～誓旦旦。\n(2)不怀疑，认为可靠～任。～托。～心。～念。\n(3)崇奉～仰。～徒。\n(4)消息～息。杳无音～。\n(5)函件～件。～笺。～鸽。～访。\n(6)随便，放任～手（随手）。～步（随意走动，散步）。～笔。～意。\n(7)同芯2”。\n(8)姓。\n疑；\nshēn：(1)古同伸”，舒展开。\n(2)古同伸”，表白。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-信"},{"id":"glyph-seal-4fe3","script":"seal","character":"俣","reading":"yǔ","description":"yǔ：大～～（魁伟的样子）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俣"},{"id":"glyph-seal-4fe6","script":"seal","character":"俦","reading":"chóu","description":"注俦,匹也。”\n同类,辈\n相比\n表示疑问,相当于谁”\n使见善不明,用心不刚,俦克尔\n俦dào 1.隐蔽。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俦"},{"id":"glyph-seal-4fe8","script":"seal","character":"俨","reading":"yǎn","description":"美艳\n宛如,十分像\n⒈恭敬，庄重美且～。\n⒉活像，很像～如白昼。\n②整齐高楼迭次，屋舍～然。\n③很像真的～然一个大人物。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俨"},{"id":"glyph-seal-4fea","script":"seal","character":"俪","reading":"lì","description":"相称;对仗,对偶\n并列,比","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俪"},{"id":"glyph-seal-4fed","script":"seal","character":"俭","reading":"jiǎn","description":"节俭,节省\n⒈节省，不浪费～省。衣着～朴。勤～办一切事业。\n⒉约束，不放纵恭～。\n⒊贫乏，歉收。旧时称青黄不接之时为\"俭月\"，荒年为\"俭岁\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俭"},{"id":"glyph-seal-4fee","script":"seal","character":"修","reading":"xiū","description":"xiū：(1)装饰，使完美～饰。～辞。装～。\n(2)整治，恢复完美～复。～治。～缮（修理）。～浚（修理疏通）。～好。～明（古代指政治清明）。\n(3)剪或削～剪。\n(4)兴建，建造～建。～筑。\n(5)编纂，撰写～书。～史。～纂。\n(6)（学问，品行方面）钻研、学习、锻炼～学。～业。～养。\n(7)长（cháng），高～长。\n(8)信奉宗教的人虔诚地学习教义，并付诸行动～行。～女。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-修"},{"id":"glyph-seal-4fef","script":"seal","character":"俯","reading":"fǔ","description":"fǔ：(1)向下，低头，与仰”相对～身。～视。～瞰。～首。～临。～拾即是。～仰。\n(2)潜伏，卧伏季秋之月蛰虫咸～在内”。\n(3)旧时公文及书信对上级或尊长的敬辞～允。～念。～恤（请求对方体恤）。～察。～顺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俯"},{"id":"glyph-seal-4ff1","script":"seal","character":"俱","reading":"jù；jv","description":"jù：(1)全，都百废～兴。声色～厉。\n(2)一起；在一起～乐部。君与～来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俱"},{"id":"glyph-seal-4ff3","script":"seal","character":"俳","reading":"pái","description":"pái：(1)古代指杂戏、滑稽戏优～。\n(2)演杂戏的艺人～优。～倡。\n(3)诙谐，玩笑，滑稽，幽默～文。～谐。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俳"},{"id":"glyph-seal-4ff6","script":"seal","character":"俶","reading":"chù；tì","description":"chù：(1)开始～扰。\n(2)作。\n(3)整理～装（整理行装）。\n(4)善令终有～”。\ntì：同倜”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俶"},{"id":"glyph-seal-4ffa","script":"seal","character":"俺","reading":"ǎn","description":"ǎn：方言，我，我们（不包括听说话的人）～要上学。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俺"},{"id":"glyph-seal-4ffe","script":"seal","character":"俾","reading":"bǐ","description":"bǐ：使～便考查。～众周知。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俾"},{"id":"glyph-seal-500c","script":"seal","character":"倌","reading":"guān","description":"guān：(1)农村中专管饲养某些家畜的人羊～儿。\n(2)旧时称服杂役的人堂～儿。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倌"},{"id":"glyph-seal-500d","script":"seal","character":"倍","reading":"bèi","description":"bèi：(1)等于原数的两个加～。事～功半。～道而行（兼程而行）。\n(2)某数的几倍等于用几乘某数二的五～是十。\n(3)更加，非常每逢佳节～思亲”。～加。～儿精神。\n(4)增益焉用亡郑以～邻？”\n(5)古同背”，背弃，背叛。\n(6)古同背”，背诵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倍"},{"id":"glyph-seal-500f","script":"seal","character":"倏","reading":"shū","description":"shū：极快地，忽然～忽。～尔。～然。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倏"},{"id":"glyph-seal-5012","script":"seal","character":"倒","reading":"dǎo；dào","description":"dǎo：(1)竖立的东西躺下来摔～。墙～了。～塌。～台。打～。卧～。\n(2)对调，转移，更换，改换～手。～换。～车。～卖。～仓。～戈。\n正；顺；\ndào：(1)位置上下前后翻转～立。～挂。～影。～置。\n(2)把容器反转或倾斜使里面的东西出来～水。～茶。\n(3)反过来，相反地～行逆施。反攻～算。～贴。\n(4)向后，往后退～退。～车。\n(5)却东西～不坏，就是旧了点。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倒"},{"id":"glyph-seal-5018","script":"seal","character":"倘","reading":"tǎng；cháng","description":"tǎng：假使，如果～或。～若。～使。～然。\ncháng：同徜”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倘"},{"id":"glyph-seal-5019","script":"seal","character":"候","reading":"hòu","description":"hòu：(1)等待等～。～车室。～选人。守～。～补。～场。～审。～诊。\n(2)看望，问好伺～。问～。\n(3)时节时～。气～。～鸟。～虫。\n(4)事物在变化中的情状火～儿。症～。\n(5)古代把五天称为一候”，现气象学上仍沿用～温（每五天的平均温度）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-候"},{"id":"glyph-seal-501a","script":"seal","character":"倚","reading":"yǐ","description":"yǐ：(1)靠着，～靠。～赖。～傍。～托。～重。\n(2)仗恃～势。～恃。～仗。\n(3)偏，歪不偏不～。\n(4)随着，和着使慎夫人鼓瑟，上自～瑟而歌”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倚"},{"id":"glyph-seal-501c","script":"seal","character":"倜","reading":"tì","description":"tì：〔～傥〕洒脱，不拘束，如风流～～”。\n〔～然〕a.超然或特出的样子；b.疏远的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倜"},{"id":"glyph-seal-501f","script":"seal","character":"借","reading":"jiè","description":"jiè：(1)暂时使用别人的财物等～用。～阅。～账。～据。～条。\n(2)暂时把财物等给别人使用～钱给人。\n(3)假托～口。～端。～故。～代。～景。～喻。～题发挥。\n(4)依靠凭～。～势。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-借"},{"id":"glyph-seal-5021","script":"seal","character":"倡","reading":"chàng；chāng","description":"chàng：(1)发动，首先提出～言，～始。～议。～导。提～。首～（首先提倡）。\n(2)古同唱”，唱和（hè）。\nchāng：(1)古代称唱戏的人～优。\n(2)古同娼”，妓女。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倡"},{"id":"glyph-seal-5026","script":"seal","character":"倦","reading":"juàn","description":"juàn：(1)疲乏疲～。～怠。～意。～容。～色。\n(2)对某种活动失去兴趣厌～。～飞（喻厌倦仕宦而归隐）。～游（厌倦游宦生涯）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倦"},{"id":"glyph-seal-5028","script":"seal","character":"倨","reading":"jù；jv","description":"jù：(1)傲慢前～后恭（先傲慢而后恭敬）。～傲。～固。～慢。\n(2)微曲（qū）～句（钝角形的称倨”；锐角形的称句”）。\n(3)古同踞”，伸开脚坐着。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倨"},{"id":"glyph-seal-5029","script":"seal","character":"倩","reading":"qiàn","description":"qiàn：(1)美好～装。～景。\n(2)请，央求～人代笔。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倩"},{"id":"glyph-seal-502a","script":"seal","character":"倪","reading":"ní","description":"ní：(1)端，边际端～（头绪）。\n(2)弱小，小孩旄～（旄”，年老，八九十岁的年纪。旄倪”，即老幼）。\n(3)分际天～（自然之分际）。\n(4)傲慢力罢，则不能毋堕～”。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倪"},{"id":"glyph-seal-502c","script":"seal","character":"倬","reading":"zhuō","description":"zhuō：显著，大～彼云汉”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倬"},{"id":"glyph-seal-502d","script":"seal","character":"倭","reading":"wō；wēi","description":"wō：古代对日作战时称日本为倭～奴。～寇。～刀。\nwēi：古同逶”，逶迤。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倭"},{"id":"glyph-seal-503a","script":"seal","character":"债","reading":"zhai","description":"喻指应兑现的事情或所造成的损失\n借贷\n债zhài欠着的钱财～务。借～。公～。还～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-债"},{"id":"glyph-seal-503c","script":"seal","character":"值","reading":"zhí","description":"zhí：(1)价值，价钱币～。产～。贬～。升～。\n(2)物和价相当，引申有意义或有价值～百元。不～一文。～当。\n(3)数学上指演算所得结果数～。比～’数～。\n(4)遇到，逢着相～。～遇。正～。\n(5)当，轮到当～。～班。～勤。～更（gēng）。～星。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-值"},{"id":"glyph-seal-503e","script":"seal","character":"倾","reading":"qīng","description":"⒈侧，斜，歪～耳。～斜。前～。\n⒊倒塌～覆。～颓。\n⒋倒出，竭尽～诉。～箱倒箧。～其全力。\n⒍相互排挤～轧。以利相～。\n①斜倒墙壁～倒。\n②佩服，钦佩令人～倒。\n③倒出把这筐果皮、纸屑～倒在垃圾箱里。\n倾qǐng 1.顷，不久。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倾"},{"id":"glyph-seal-5043","script":"seal","character":"偃","reading":"yǎn","description":"yǎn：(1)仰面倒下，放倒～卧。～仆。～仰（俯仰，喻随俗应付）。～旗息鼓。\n(2)停止～息。～武修文。\n(3)古同堰”，堤坝。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偃"},{"id":"glyph-seal-5047","script":"seal","character":"假","reading":"jiǎ；jià","description":"jiǎ：(1)不真实的，不是本来的，与真”相对～山。～话。～冒。～释。～死。虚～。真～。弄虚作～。\n(2)借用，利用～借。～货。～道（借路）。～手（利用他人为自己办事）。～公济私。不～思索（用不着想）。\n(3)据理推断，有待验证的～设。～使。～令。～如。～若。\n〔～名〕日本文所用的字母，多借用汉字的偏旁。楷书称片～～”，草书称平～～”。\n真；\njià：照规定或经请求批准暂时离开工作或学习场所～日。～条。病～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-假"},{"id":"glyph-seal-504f","script":"seal","character":"偏","reading":"piān","description":"piān：(1)歪，不在中间～斜。～离。～旁。～僻。～远。～锋（a.书法上指用毛笔时笔锋斜出的笔势；b.泛指做文章从侧面着手的方法）。不～不倚。\n(2)不全面，不正确～爱。～见。～激。～狭。～执。～废。～颇。～听～信。\n(3)与愿望、预料或一般情况不相同～～。～巧。\n(4)谦辞，向人称自己已用过茶饭等我～过了，您请吃吧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偏"},{"id":"glyph-seal-5055","script":"seal","character":"偕","reading":"xié","description":"xié：(1)共同，在一起～老（夫妇同居到老，如白头～～”）。～行（xíng）。～同。～乐（lè）。\n(2)和谐五字诗成卷，清诗少得～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偕"},{"id":"glyph-seal-505c","script":"seal","character":"停","reading":"tíng","description":"tíng：(1)止住，中止不动～止。～产。～学。～职。～顿。～刊。～战。～业。～滞。\n(2)总数分成几份，其中的一份十～儿有九～儿是好的。\n(3)暂时不继续前进～留。～泊。\n(4)妥当～妥。～当。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-停"},{"id":"glyph-seal-5065","script":"seal","character":"健","reading":"jiàn","description":"jiàn：(1)强壮，身体好～康。～全。康～。稳～。～美。～身。～旺。～在。～壮。～朗。保～。\n(2)善于，精力旺盛～步如飞。～谈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-健"},{"id":"glyph-seal-5076","script":"seal","character":"偶","reading":"ǒu","description":"ǒu：(1)用木头或泥土等制成的人形～像。木～戏。\n(2)双，对，成双成对，与奇（jī）”相对～数。～语（相对私语）。对～。无独有～。\n(3)事理上不一定要发生而发生的～或。～然。～合。～尔。～感。～发事件。\n(4)指丈夫或妻子佳～。配～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偶"},{"id":"glyph-seal-507b","script":"seal","character":"偻","reading":"lǚ；lou","description":"见佝偻”\n⒈屈～身。\n⒉驼背～人。\n⒊迅速～售。\n偻liǔ 1.丧车的装饰物。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偻"},{"id":"glyph-seal-507e","script":"seal","character":"偾","reading":"fèn","description":"覆,翻倒在地\n覆败\n使灭亡\n毁坏;败坏\n⒈败坏，毁坏～事。～军之将。\n⒉扑倒，跌倒一～一起。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偾"},{"id":"glyph-seal-507f","script":"seal","character":"偿","reading":"cháng","description":"报答;酬报\n补偿,抵偿\n满足,实现\n酬报\n①归还；低偿血债要用血来～。\n②满足如愿以～。\n【偿命】用生命偿还杀人～。\n⒈归还，赔给～还。～债。赔～。\n⒉抵当，抵补抵～。补～。得不～失。\n⒊回报，回答不可～也。\n⒋满足，实现如愿以～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偿"},{"id":"glyph-seal-5080","script":"seal","character":"傀","reading":"guī；kuǐ","description":"kuǐ：〔～儡〕ａ．木偶戏里的木头人；ｂ．喻徒有虚名，被人操纵的人或组织，如～～政权”。\nguī：(1)怪异～奇（亦作瑰奇”）。\n(2)独立的样子～然独立。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傀"},{"id":"glyph-seal-5085","script":"seal","character":"傅","reading":"fù","description":"fù：(1)辅相太～。少～。\n(2)教导～立德义”。\n(3)教导人的人师～。\n(4)附着，使附着～粉。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傅"},{"id":"glyph-seal-508d","script":"seal","character":"傍","reading":"bàng","description":"bàng：(1)靠依山～水。\n(2)临近～晚。～黑。～亮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傍"},{"id":"glyph-seal-50a5","script":"seal","character":"傥","reading":"tǎng","description":"怅然自失,恍惚\n正直\n广大\n安闲自得\n⒈同上\"倘\"。\n傥tàng 1.侥幸;偶然。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傥"},{"id":"glyph-seal-50a7","script":"seal","character":"傧","reading":"bīn","description":"字亦作攑。注出接宾曰摈。”\n陈列,摆\n通摈”。排斥,抛弃\n傧厥亲\n①导引宾客或以礼迎宾。\n②指侍从的人。\n③陈列。\n④通\"攑\"。排斥;弃绝。\n傧bīn 1.尊敬。\n傧pín 1.皱眉。参见\"傧笑\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傧"},{"id":"glyph-seal-50a8","script":"seal","character":"储","reading":"chǔ","description":"夸大,欺诳\n①存放；储藏～存、～蓄。\n②姓。\n【储君】帝王亲属中确定为继承皇位等最高统治权的人。\n【储蓄】\n①指积存的钱或物家家有～。\n②居民把暂时不用的现金存入银行或其他信用机构，以备需要时取用。\n储chǔ存，积蓄，藏着～存。～积。～蓄。～藏。～备。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-储"},{"id":"glyph-seal-50a9","script":"seal","character":"傩","reading":"nuó","description":"指古迎神赛会\n傩神\n傩戏","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傩"},{"id":"glyph-seal-50ac","script":"seal","character":"催","reading":"cuī","description":"cuī：(1)使赶快行动～促。～办。～讨。\n(2)使事物的产生、发展变化加快～化。～生。～眠。～奶。～肥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-催"},{"id":"glyph-seal-50b2","script":"seal","character":"傲","reading":"ào","description":"ào：(1)自高自大骄～。～岸（形容性格高傲）。～骨。～慢（轻视别人，对人没有礼貌）。～视。高～。孤～。\n(2)藐视，不屈～然。～霜斗雪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傲"},{"id":"glyph-seal-50cf","script":"seal","character":"像","reading":"xiàng","description":"xiàng：(1)相似好～。相（xiāng）～。～生（ａ．仿天然产物制成的工艺品；ｂ．中国宋、元两代以说唱为业的女艺人）。\n(2)比照人物做成的图形画～。塑～。雕～。绣～。肖～。\n(3)比如，比方～这样的事是值得注意的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-像"},{"id":"glyph-seal-50d6","script":"seal","character":"僖","reading":"xī","description":"xī：(1)喜乐。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僖"},{"id":"glyph-seal-50da","script":"seal","character":"僚","reading":"liáo","description":"liáo：(1)官官～。\n(2)旧指同在一起做官的～属（下属的官吏）。～友。～佐。幕～。\n(3)古代对一种奴隶或差役的称谓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僚"},{"id":"glyph-seal-50e7","script":"seal","character":"僧","reading":"sēng","description":"sēng：佛教指出家修行的人，梵语僧伽”的简称～侣。～尼。～人。～众。～俗。高～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僧"},{"id":"glyph-seal-50ed","script":"seal","character":"僭","reading":"jiàn","description":"jiàn：超越本分，古代指地位在下的冒用在上的名义或礼仪、器物～越。～妄。～伪（封建王朝称割据对立的王朝）。～盗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僭"},{"id":"glyph-seal-50ee","script":"seal","character":"僮","reading":"tóng；zhuàng","description":"tóng：(1)封建时代受奴役的未成年人书～。～仆。\n(2)古同童”。\nzhuàng：〔～族〕中国少数民族，今改作壮族”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僮"},{"id":"glyph-seal-50f0","script":"seal","character":"僰","reading":"mán；bó；màn","description":"僰màn 1.轻视，轻慢。 2.犹轻易。 3.怠惰。 4.通\"漫\"。污。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僰"},{"id":"glyph-seal-50f5","script":"seal","character":"僵","reading":"jiāng","description":"jiāng：(1)仆倒～尸。\n(2)直挺挺，不灵活冻～。～硬。～直。～化。～卧。～死。～冷。～滞。\n(3)双方相持不下，两种意见不能调和弄～。～持。～局。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僵"},{"id":"glyph-seal-50fb","script":"seal","character":"僻","reading":"pì","description":"pì：(1)偏，距离中心地区远的偏～。～静。～陋。～野。～远。穷乡～壤。\n(2)不常见的冷～。生～。\n(3)性情古怪，不合群孤～。怪～。乖～。～戾。～性。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僻"},{"id":"glyph-seal-5106","script":"seal","character":"儆","reading":"jǐng","description":"jǐng：(1)使人警醒，不犯过错～戒。～省（xǐng）（使人觉悟、反省）。惩一～百。以～效尤。\n(2)古同警”，警报。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-儆"},{"id":"glyph-seal-510b","script":"seal","character":"儋","reading":"dān；dàn","description":"dān：〔～县〕地名，在中国海南省。\ndàn：古同担”，负荷。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-儋"},{"id":"glyph-seal-5112","script":"seal","character":"儒","reading":"rú","description":"rú：(1)指读书人～生。腐～。通～（指博识多闻的大学者）。～林（儒者之林，旧指学术界）。～雅（读书人所具有的温文尔雅的风貌）。\n(2)中国春秋战国时代以孔子、孟子为代表的一个学派～家。～教（即孔教”）。～士。～术。～学。\n(3)古同懦”，懦弱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-儒"},{"id":"glyph-seal-5121","script":"seal","character":"儡","reading":"lěi","description":"lěi：〔傀（kuǐ）～〕见傀1”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-儡"},{"id":"glyph-seal-513f","script":"seal","character":"儿","reading":"ér","description":"儿女,父母所生的子女,第一代后裔\n①小孩子婴～。\n③儿子～女。\n④词尾，同前一字连成一个卷舌音小孩～。\n【儿歌】儿童文学的一种。一般与童谣合称为儿童歌谣。儿歌是指反映儿童的生活和思想感情的诗歌。形式短小活泼，用辞简明，节奏明快，韵律响亮，适合儿童接受和传唱。\n童谣则指流传于儿童中间的歌谣。\n【儿化】〈语〉汉语普通话和某些方言中的一种语音现象，即后缀'儿'字不自成音节，而和前头的音节合在一起，使前一音节的韵母成为卷舌韵母。又叫儿化韵。\n【儿化韵】见【儿化】。\n【儿童节】见【六一儿童节】。\n【儿童文学】适合少年儿童阅读的各种体裁的文学作品。包括童话、诗歌、小说、故事、戏剧等形式，要求通俗易懂、生动活泼，适应不同年龄的少年儿童的智力和爱好。\n【儿童心理学】心理学分支之一。研究儿童心理发生、发展的一般规律及各年龄阶段的心理特征。\n【儿戏】像小孩子那么闹着玩。比喻对重要的工作或事情不负责、不认真视同～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-儿"},{"id":"glyph-seal-5140","script":"seal","character":"兀","reading":"wū；wù","description":"wù：(1)高而上平，形容秃山，泛指秃～鹫。蜀山～，阿房出。”\n(2)高高地突起～然（a.高高突起的样子；b.突然；c.昏沉无知的样子）。突～。\n(3)中国元曲中用作发语词～那。～的（dì）（a.这，这个；b.怎么，怎的；c.突然）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兀"},{"id":"glyph-seal-5141","script":"seal","character":"允","reading":"yǔn","description":"yǔn：(1)答应，认可～许。～诺。不～。\n(2)公平得当～当。公～。\n(3)信，实～恭克让（诚信，谦逊能够忍让）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-允"},{"id":"glyph-seal-5143","script":"seal","character":"元","reading":"yuán","description":"yuán：(1)头、首、始、大～凶。～首。～旦。～年。～勋。～帅。状～（科举考试第一名）。\n(2)基本单～。～件。～气（精气，根本）。～素。～音。\n(3)同圆”⑦。\n(4)未知数一～二次方程。\n(5)中国朝代名～代。～曲。\n(6)姓。\n(7)古同玄”，清代避康熙皇帝（玄烨）名讳，以元”代玄”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-元"},{"id":"glyph-seal-5144","script":"seal","character":"兄","reading":"xiōng","description":"xiōng：哥哥胞～。堂～。表～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兄"},{"id":"glyph-seal-5145","script":"seal","character":"充","reading":"chōng","description":"chōng：(1)满、足～足。～实。～分（fèn）（a.足够；b.尽量）。～沛。～裕。\n(2)填满，装满填～。～满（a.填满，布满；b.充分具有）。～耳不闻。～电」牛～栋。\n(3)当，担任～当。～军。\n(4)假装冒～。～数（shù）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-充"},{"id":"glyph-seal-5146","script":"seal","character":"兆","reading":"zhào","description":"zhào：(1)古代占验吉凶时灼龟甲所成的裂纹卜～。\n(2)事物发生前的征候或迹象，预示预～。佳～。瑞雪～丰年。\n(3)数名，等于百万（古代指万亿）～周（电磁波频率单位，每秒一百万周的频率为一兆周）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兆"},{"id":"glyph-seal-5148","script":"seal","character":"先","reading":"xiān","description":"xiān：(1)时间在前的，次序在前的，与后”相对～前。～期。原～。～驱。～河（中国古代帝王先祭黄河，后祭海，以河为海的本源，后称倡导在先的事物）。～觉（jué）。～见之明。～发制人。\n(2)家族或民族的较早的一代或几代～人。～世（祖先）。～民。\n(3)对死去的人的尊称～祖。～父。～哲（指已去世的有才德的思想家）。～烈。～贤。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-先"},{"id":"glyph-seal-5149","script":"seal","character":"光","reading":"guāng","description":"⒈光线，照亮物体因而可用眼睛看到物体的那种东西～亮。～芒。日～。电灯～。～的传播速度，每秒约30万公里。〈喻〉心怀坦白，公正无私～明磊落。正大～明。\n⒉荣耀，荣誉，耀眼的～彩。～荣。～辉灿烂。\n⒊敬词欢迎～临。谢谢～顾。\n⒋景物春～明媚。美好风～。\n①境况，情景我们的～景一年更比一年强。\n②〈表〉估计看～景怕是要下雨。\n⒌表面平滑，使平滑～滑。～溜溜。打～。刨～。\n⒍完，一点儿不剩吃～。消灭～。\n⒎裸露～脚行走。～着上身。\n⒏只，单～剩这一间屋了。～靠少数人是做不好这件事的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-光"},{"id":"glyph-seal-514b","script":"seal","character":"克","reading":"kè","description":"⒈至\n⒋剋、\n⒈至\n⒈攻破，战胜连～数城。～敌制胜。\n⒉制伏，抑制～服。～制。奉公～己。\n⒋通\"刻\"。雕刻，苛刻～画。性俭～。\n⒌能够～勤～俭。～尽职责。\n⒍消化～食。\n⒎公制重量单位，旧称\"公分\"。一千克为一公斤。\n⒏藏族地区的容量单位，一克青稞约为二十五市斤。也是土地的面积单位，一克约为一市亩。\n克kēi 1.训斥;狠狠批评。 2.方言。抠取。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-克"},{"id":"glyph-seal-514d","script":"seal","character":"免","reading":"miǎn","description":"miǎn：(1)去掉，除掉～除。～税。～费。～官。～检。罢～。豁～。\n(2)不被某种事物所涉及避～。～疫。～不了。在所难～。\n(3)不可，不要闲人～进。\n(4)古同勉”，勉励。\n(5)古同娩”，分娩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-免"},{"id":"glyph-seal-5151","script":"seal","character":"兑","reading":"duì；ruì；yuè","description":"duì：(1)交换～换（用一种货币换另一种货币）。～现。汇～（两地通过信件或电报交换款项）。\n(2)液体从一个容器注入另一个容器，一种东西搀到另一种东西里去～点热水。\n(3)八卦之一，代表沼泽。\n(4)直松柏斯～”。\nruì：古同锐”，尖锐。\nyuè：古同悦”，喜悦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兑"},{"id":"glyph-seal-5154","script":"seal","character":"兔","reading":"tù","description":"tù：(1)哺乳动物，耳长，尾短，上唇中间裂开，后肢较长，跑得快～子。～脱（迅速地逃走）。～毫笔。～起鹘落（鹘”，打猎用的猛禽。兔子才起来而鹘已经扑下去，喻动作敏捷。亦喻作书画或写文章下笔迅捷）。\n(2)古称娈童（指被当作女性玩弄的美貌男子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兔"},{"id":"glyph-seal-5155","script":"seal","character":"兕","reading":"sì","description":"sì：古书上所说的雌犀牛。\n〔～觥〕古代一种酒器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兕"},{"id":"glyph-seal-515a","script":"seal","character":"党","reading":"dǎng","description":"不鲜明\n美,善,正直◇作谠”\n知晓,解悟\n偏私,偏袒\n①政党，代表某一阶级、阶层利益的政治组织。在我国特指中国共产党。\n②为私利而结成的集团结～营私。\n③偏袒～同伐异。\n④旧时指亲族父～、母～。\n⑤姓。\n【党阀】政党内把持大权、专横跋扈、拉山头、搞宗派的头目。\n【党锢之祸】东汉末因宦官专权而对世家大族进行的打击。第一次党锢之祸发生在恒帝时，李膺等抨击宦官集团，被诬为诽讪朝廷，200多名'党人'被捕，释放后终身不许做官\n。第二次党锢之祸发生在灵帝时，窦武起用'党人'谋诛宦官，事泄被杀。李膺等百余人亦被处死，流徙囚禁六七百人。被禁锢罢官者，祸及'党人'五族。\n【党同伐异】偏袒同党，攻击异己。\n【党卫军】第二次世界大战期间法西斯德国纳粹党的特务和军事组织。成立于1925年。最初为希特勒的私人卫队。希特勒执政后成为特务机构。曾以血腥手段迫害和屠杀德国国\n内进步势力、占领区居民和犹太人，并直接参加法西斯侵略战争。1946年在纽伦堡审判中被定为犯罪组织。\n【党项人】古族名。羌人的一支。原分布于青海、四川一带，主要从事畜牧业。唐时受吐蕃压迫，迁至甘肃、宁夏、陕北一带。北宋时曾建立西夏政权。\n【党羽】反动集团中与头领一起为非作歹的帮凶。\n【党政分工】指党组织和行政部门的领导分工负责。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-党"},{"id":"glyph-seal-515c","script":"seal","character":"兜","reading":"dōu","description":"dōu：(1)古代作战时戴的盔～鍪。\n(2)口袋网～。\n(3)做成兜形把东西拢住～风。用手巾～着。\n(4)环绕，围绕～抄。～剿。～圈子。\n(5)招揽～售。～销。～揽。\n(6)承担，包下来出事我～着。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兜"},{"id":"glyph-seal-5162","script":"seal","character":"兢","reading":"jīng","description":"jīng：〔～～〕小心，谨慎，如～～业业”、战战～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兢"},{"id":"glyph-seal-5165","script":"seal","character":"入","reading":"rù","description":"rù：(1)进，由外到内进～。～梦。\n(2)适合，恰好合适～选。～耳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-入"},{"id":"glyph-seal-5168","script":"seal","character":"全","reading":"quán","description":"quán：(1)完备，齐备，完整，不缺少齐～。完～。智勇双～。求～责备。\n(2)整个，遍～部。～国。～民。～神贯注。～心～意。\n(3)都代表～来了。\n(4)使不受损伤保～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-全"},{"id":"glyph-seal-516b","script":"seal","character":"八","reading":"bā","description":"bā：数名，七加一（在钞票和单据上常用大写捌”代）～面玲珑。～卦（《周易》中的八种基本图形）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-八"},{"id":"glyph-seal-516c","script":"seal","character":"公","reading":"gōng","description":"gōng：(1)正直无私，为大家利益～正。～心。大～无私。\n(2)共同的，大家承认的～理。～式。～海。～制。\n(3)国家，社会，大众～共。～安（社会整体的治安）。～众。～民。～论（公众的评论）。\n(4)让大家知道～开。～报。～然。\n(5)封建制度最高爵位三～（中国周代指太师”、太傅”、太保”；西汉指大司徒”、大司马”、大司空”）。～子。～主。\n(6)敬辞，尊称男子海～。包～。诸～（各位）。\n(7)雄性的～母。～畜。\n(8)对长辈和年老人的称呼～～。外～（外祖父）。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-公"},{"id":"glyph-seal-516d","script":"seal","character":"六","reading":"liù；lù","description":"(2)中国古代乐谱的记音符号，相当于简谱5”。\nlù：〔～安〕地名，在中国安徽省。\n〔～合〕地名，在中国江苏省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-六"},{"id":"glyph-seal-516e","script":"seal","character":"兮","reading":"xī","description":"xī：文言助词，相当于现代的啊”或呀”路漫漫其修远～，吾将上下而求索”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兮"},{"id":"glyph-seal-5170","script":"seal","character":"兰","reading":"lán","description":"兰花\n兰属\n⒈兰花，多年生常绿草本，丛生，叶细长，花清香。种类很多，常见的有草～、建～、墨～、蕙～等。供观赏。\n⒉兰草，多年生草本。叶子卵圆形，边缘呈锯齿状，有香味，秋末开花，供观赏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兰"},{"id":"glyph-seal-5171","script":"seal","character":"共","reading":"gòng；gōng","description":"gòng：(1)相同，一样～性。～同。同甘～苦。\n(2)彼此都具有、使用或承受患难与～。休戚与～。\n(3)一起，一齐～鸣。～勉。～议。～处（chǔ）。\n(4)总计，合计～计。总～。\n(5)与，和落霞与孤鹜齐飞，秋水～长天一色。”\n(6)共产党”的简称。\n同；\ngōng：(1)古同恭”，恭敬。\n(2)古同供”，供奉，供给。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-共"},{"id":"glyph-seal-5173","script":"seal","character":"关","reading":"guān","description":"门闩。闩门的横木\n关口,隘门\n⒈闭，合把门～上。～好窗子。〈引〉拘禁～押。\n⒉门闩拔～而出。\n⒊〈古〉要塞或设立守卫的处所～口。剑门～。〈引〉征收出口、进口货物税的机构海～。\n⒋重要的转折点或不易度过的时机紧要～头。共度难～。\n⒌起转折和联结作用的部分腕～节。\n⒍牵连，涉及～连。～联。息息相～。与他无～。\n⒎重视，爱护，照顾～注。～切。～心。～怀。请多～照。\n①事物间的联系学习与工作的～系。\n②人与人或人与事物的联系朋友～系。人与环境的～系。\n③牵涉，影响这项事～系重大。\n④〈表〉某种证件党的组织～系。\n⑤泛指原因、条件等由于时间～系，不再讲了。\n关wān 1.引满弓。\n关wǎn 1.绾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-关"},{"id":"glyph-seal-5174","script":"seal","character":"兴","reading":"xīng","description":"⒉发动，举办，提倡～修水利。～办工厂。大～勤俭节约之风。\n⒊旺盛～旺。～盛。\n⒋流行，盛行～起。时～。\n⒌允许不～乱吵。\n⒍〈方〉或许你～买，～不买。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兴"},{"id":"glyph-seal-5175","script":"seal","character":"兵","reading":"bīng","description":"bīng：(1)武器～器。～刃。～不血刃（兵器上面没有沾血，指不经过战斗而取得胜利）。\n(2)战士，军队～士。～卒。～丁。～戎相见（指武装冲突）。\n(3)与军事或战争有关事物的统称～法。～家。～机。～衅（战争的争端）。～书。～谏（进谏时以武力要挟，迫使必从）。～荒马乱。～贵神速。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兵"},{"id":"glyph-seal-5176","script":"seal","character":"其","reading":"qí；jī","description":"qí：(1)第三人物代词，相当于他（她）”、他们（她们）”、它（它们）”；他（她）的”、他们（她们）的”、它（们）的”各得～所。莫名～妙。三缄～口。独行～是。自食～果。\n(2)指示代词，相当于那”、那个”、那些”～他。～余。～次。文如～人。名副～实。言过～实。\n(3)那里面的～中。只知～一，不知～二。\n(4)连词，相当于如果”、假使”～如是，熟能御之？”\n(5)助词，表示揣测、反诘、命令、劝勉～如土石何？”\n(6)词尾，在副词后极～快乐。大概～。\njī：〔郦食（yì）～〕中国汉代人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-其"},{"id":"glyph-seal-5177","script":"seal","character":"具","reading":"jù；jv","description":"jù：(1)器物器～。\n(2)备有～备。～有。别～只眼（形容具有独到的眼光和见解）。\n(3)备，办～呈。～结。～名。～领。敬～菲酌。\n(4)古同俱”，都，完全。\n(5)量词，用于某些器物和棺材、尸体座钟一～。一～男尸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-具"},{"id":"glyph-seal-5178","script":"seal","character":"典","reading":"diǎn","description":"diǎn：(1)可以作为标准的书籍～籍。字～。词～。经～。引经据～。\n(2)标准，法则～章。～制。～故（a.典制和掌故；b.诗文里引用的古书中的故事或词句）。～范。～雅。～礼。～型。\n(3)指典礼盛～。大～。\n(4)主持，主管～试（主持科举考试之事）。～狱。\n(5)活买活卖，到期可以赎～卖。～押。～契。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-典"},{"id":"glyph-seal-5179","script":"seal","character":"兹","reading":"zī；cí","description":"zī：(1)这，这个，此～日。～行（xíng）。\n(2)现在～聘请某先生为本校教员。\n(3)年今～。来～。\n(4)古同滋”，增益；多。\n(5)古代称草席。\ncí：〔龟（qiū）～〕见龟3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兹"},{"id":"glyph-seal-517b","script":"seal","character":"养","reading":"yǎng","description":"供养,奉养;抚育\n监门之养。\n供养卒大恩。\n⒈抚育，供给～育。供～。\n⒉生育，生小孩生～。\n⒊教育，培育教～。培～。从小～成劳动习惯。\n⒋喂动物，培植花草饲～。～鸭。～猪。～殖。～鸟。～花。～草。\n⒌休息，调理，滋补。休～。保～。滋～。〈引〉保护修理 修～。～路。\n⒍扶助，帮助以工～农。\n⒎非亲生的但有抚育关系的～母。～女。\n久长。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-养"},{"id":"glyph-seal-517c","script":"seal","character":"兼","reading":"jiān","description":"jiān：(1)加倍，把两份并在一起～旬（两个十天）。～程。～并。\n(2)同时涉及或所具有的不只一方面～而有之。～收并蓄。～顾。～职。～任。～课。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兼"},{"id":"glyph-seal-517d","script":"seal","character":"兽","reading":"shòu","description":"四足的哺乳动物,多指野兽\n山深而兽往之","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兽"},{"id":"glyph-seal-5180","script":"seal","character":"冀","reading":"jì","description":"jì：(1)希望～求（希望得到）。～幸。～望。～希。\n(2)中国河北省的别称。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冀"},{"id":"glyph-seal-5185","script":"seal","character":"内","reading":"nèi；nà","description":"nèi：(1)里面，与外”相对～部。～外。～定。～地。～阁。～行（háng）。～涵。\n(2)称妻子或妻子家的亲戚～人。～亲。～弟。\n(3)亲近～君子而外小人。\n外；\nnà：古同纳”，收入；接受。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-内"},{"id":"glyph-seal-5188","script":"seal","character":"冈","reading":"gāng","description":"较低而平缓的山脊，如山冈。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5189","script":"seal","character":"冉","reading":"rǎn","description":"rǎn：(1)龟甲的边。\n(2)姓。\n〔～～〕a.毛、枝条等柔软下垂；如柳枝～～”；b.慢慢地，如月亮～～升起”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冉"},{"id":"glyph-seal-518c","script":"seal","character":"册","reading":"cè","description":"cè：(1)古代称编串好的竹简，现在指装潢好的纸本子纪念～。花名～。画～。\n(2)量词，指书籍一～书。\n(3)古代帝王祭祀天地神仙的文书或封爵的诏书～文（文体名，为册命、册书等诰命文字的一种。简称册”）。～命。～封。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-册"},{"id":"glyph-seal-518d","script":"seal","character":"再","reading":"zài","description":"zài：(1)表示又一次，有时专指第二次，有时又指多次～次。～衰三竭。\n(2)表示重复或继续，多指未然～说。\n(3)表示更，更加～勇敢一点。\n(4)表示承接前一个动作想好了～写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-再"},{"id":"glyph-seal-5192","script":"seal","character":"冒","reading":"mào；mò","description":"mào：(1)向外透或往上升～烟（a.烟往上升；b.发怒）。～汗。～尖。\n(2)不顾（恶劣的环境或危险等），顶着～雨。～险。～死。\n(3)不加小心，鲁莽，冲撞～失。～昧。～进（不顾具体条件，急躁进行）。\n(4)用假的充当真的，假托～牌。～充。～名顶替。\n(5)复盖先设一铁板，其上以松脂、蜡和纸灰之类～之”。\n(6)贪污贪于饮食，～于货贿”。\n(7)古同帽”。\n(8)古同瑁”，玳瑁。\n(9)姓。\nmò：〔～顿（dú）〕中国汉初匈奴族的一个君主名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冒"},{"id":"glyph-seal-5195","script":"seal","character":"冕","reading":"miǎn","description":"miǎn：中国古代帝王及地位在大夫以上的官员们戴的礼帽，后专指帝王的皇冠冠～。加～。卫～（卫护帝王头上的皇冠，喻维护帝王的最高统治权力或保持体育竞赛中的上届冠军称号）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冕"},{"id":"glyph-seal-5197","script":"seal","character":"冗","reading":"rǒng","description":"rǒng：(1)闲散的，多余无用的～人。～长（cháng）。～员。～赘。\n(2)忙，繁忙的事拨～（忙中抽出时间）。～务缠身。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冗"},{"id":"glyph-seal-5199","script":"seal","character":"写","reading":"xiě","description":"输送\n倾吐,倾诉;抒发\n⒈摹画，描述～生。～实。\n⒉指书写～字。～文章。\n写xiè 1.倾泻。 2.疏泄。中医治疗方法之一。与\"补\"相对。 3.通\"卸\"。把东西解取或搬运下来。 4.泛指解除，脱卸。 5.泄漏;泄露。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-写"},{"id":"glyph-seal-519b","script":"seal","character":"军","reading":"jūn","description":"注犹屯兵粮储也。”\n攻杀\n指挥作战\n⒈武装部队～队。空～。～。陆～。\n⒉军队的编制单位，它是师的上一级。\n⒊泛指军事的或有组织的集体～机。～令。抗洪大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-军"},{"id":"glyph-seal-519c","script":"seal","character":"农","reading":"nóng","description":"⒈种庄稼，种庄稼的～活。～业。务～。\n⒉农民贫～。菜～。工～联盟。亦工亦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-农"},{"id":"glyph-seal-51a0","script":"seal","character":"冠","reading":"guàn；guān","description":"guān：(1)帽子衣～。～戴。～盖（古代官吏的帽子和车盖，借指官吏）。衣～楚楚。\n(2)形状像帽子或在顶上的东西～子。鸡～。树～。～状动脉。\nguàn：(1)把帽子戴在头上沐猴而～。\n(2)超出众人，居第一位～军。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冠"},{"id":"glyph-seal-51a2","script":"seal","character":"冢","reading":"zhǒng","description":"zhǒng：(1)坟墓古～。荒～。衣冠～。青～。丛～。\n(2)长（zhǎng）～子（长子）。～嗣（嫡长子）。～妇（嫡长子的妻子）。～息（长子）。\n(3)大～君（大君，对列国君主的敬称）。～祀（帝王在宗庙举行的大祭礼）。\n(4)山顶。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冢"},{"id":"glyph-seal-51a4","script":"seal","character":"冤","reading":"yuān","description":"yuān：(1)屈枉，无故受到指责或处分～枉。～屈。～案。～狱。～愤。伸～。鸣～叫屈。\n(2)仇恨～头。～家。～孽。\n(3)欺骗不许～人。\n(4)吃亏，上当～大头。花～钱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冤"},{"id":"glyph-seal-51a5","script":"seal","character":"冥","reading":"míng","description":"míng：(1)昏暗幽～。～蒙。晦～。\n(2)深奥，深沉～思。～想。～心。\n(3)糊涂，愚昧～顽不灵。\n(4)迷信的人称人死后进入的世界～界。～府。～婚。～衣。～寿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冥"},{"id":"glyph-seal-51ac","script":"seal","character":"冬","reading":"dōng","description":"一年四季中秋春之间的季节,天文学上认为是从12月至3月,农历十月到十二月\n冬月,阴历十一月的俗称\n最后,\n①四季中的第四季，气候最冷严～。\n②象声词。敲鼓或敲门声。\n③姓。\n【冬不拉】哈萨克族民族弹拨乐器。琴腹为半梨形，琴杆细而长。指板上装有9至12个品位。张弦2根或4根，4度或5度定弦，音高不固定。音色清秀、优美，音量不太大。\n【冬草】见【冬虫夏草】。\n【冬虫夏草】参见【虫草】。\n【冬宫】世界著名宫殿。在列宁格勒。始建于18世纪，原为俄国沙皇的宫殿，1917年二月革命后成为资产阶级临时政府所在地。十月革命中遭阿芙乐尔巡洋舰炮击，并被工人、\n士兵占领。现辟为博物馆。\n【冬菇】见【香菇】。\n【冬瓜】葫芦科，一年生草本。茎上有卷须，叶大，开黄花，果实球形或长圆柱形，表面有毛和白色粉状物。是普通蔬菜。种子和皮可入药。原产我国南部和印度。又叫白瓜。\n【冬烘】迂腐浅薄～先生。\n【冬候鸟】冬季在某个地区生活，春季飞到较冷的地区繁殖，秋季又飞回原地区的鸟。如大雁就是我国的冬候鸟。\n【冬季风】因海陆差异，冬季大陆气温低于海洋，产生高气压，海洋上是低气压，故空气从大陆流向海洋，形成冬季风。在我国冬季经常出现从亚洲内陆吹向海洋的偏北风。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冬"},{"id":"glyph-seal-51af","script":"seal","character":"冯","reading":"féng","description":"古地名\n大,盛\n徒步过水\n⒈姓。\n⒉〈古〉通\"piηp凭\"。\n冯píng 1.马行疾。引申为激怒，愤懑。 2.大;盛大;满。参见\"冯怒\"﹑\"冯闳\"。 3.贪得;贪求。参见\"冯生\"。 4.欺陵;侵侮。 5.挟持。参见\"冯珧\"。 6.徒涉;蹚水。\n7.登;乘。 8.\"凭\"的古字。依着;靠着。 9.\"凭\"的古字。亦指所靠之物。 10.\"凭\"的古字。凭借;依恃。 11.通\"朋\"。古代计算货币的单位。上古以贝壳为货币，五贝为\n一串，两串为一朋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冯"},{"id":"glyph-seal-51b0","script":"seal","character":"冰","reading":"bīng","description":"bīng：(1)水因冷凝结成的固体～块。～凌。～箱。～窖。～雕。～封。～球。～镇。～释（像冰一样融化，喻嫌隙、怀疑、误会等完全消除）。～淇淋。\n(2)结晶成固体，呈结晶形的～糖。～晶石。\n(3)使人感到寒冷～手～脚。\n(4)用冰贴近东西使其变凉把汽水～上。\n(5)洁白明彻～绡。～心。～清玉洁。～肌玉骨（a.形容妇女的皮肤；b.形容梅花的高洁）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冰"},{"id":"glyph-seal-51b2","script":"seal","character":"冲","reading":"chōng","description":"直上\n以水、酒等浇注调制\n使曝光过的照相材料显影\n用水或其他液体冲洗\n深远","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冲"},{"id":"glyph-seal-51b3","script":"seal","character":"决","reading":"jué","description":"jué：(1)排除阻塞物，疏通水道禹～江疏河”。\n(2)堤岸被水冲开～口。溃～。\n(3)断定，拿定主意～定。～断。～计。～然。～胜。～议。犹豫不～。\n(4)一定（用在否定词前）～不后退。\n(5)决定最后胜败～赛。～战。\n(6)执行死刑处～。枪～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-决"},{"id":"glyph-seal-51b5","script":"seal","character":"况","reading":"kuàng","description":"kuàng：(1)情形情～。状～。近～。～味（境况和情味，如他的处境不好，～～难言”）。\n(2)比方比～。每～愈下。\n(3)文言连词，表示更进一层～且∥～。\n(4)姓。\n(5)古同贶”，赐予。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-况"},{"id":"glyph-seal-51b6","script":"seal","character":"冶","reading":"yě","description":"yě：(1)熔炼金属～炼。～铸。～金。\n(2)好过分的装饰打扮（含贬义）～容（a.打扮得很妖艳；b.妖艳的容貌）。妖～。\n(3)古同野”～游（原指春天或节日里男女出外游玩，后专指狎妓）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冶"},{"id":"glyph-seal-51b7","script":"seal","character":"冷","reading":"lěng","description":"lěng：(1)温度低，与热”相对～天。～藏。～冻。～涩。～飕飕。\n(2)寂静，不热闹～落。～寂。～静。～清。\n(3)生僻，少见的～僻。～字。\n(4)不热情，不温和～遇。～淡。～峻。～漠。～嘲热讽。～若冰霜。～酷无情。\n(5)不受欢迎的，没有人过问的～货。～门儿。\n(6)突然，意料以外的～然。～不防。～枪。～战。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冷"},{"id":"glyph-seal-51bb","script":"seal","character":"冻","reading":"dòng","description":"受冻;感到寒冷\n厚冰\n汁液或其他含\n②汤汁类凝结成半固体肉～。\n③感到寒冷或受到寒冷脚～了。\n【冻土】指温度在0℃以下，因冻结而含冰的各种土石层。按保持时间可分为暂时性冻土、多年冻土和季节性冻土。多年冻土在地球上的分布约占陆地面积的1/4，主要分布在苏\n联和加拿大。\n冻dōng 1.见\"冻雨\"﹑\"冻冻\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冻"},{"id":"glyph-seal-51bd","script":"seal","character":"冽","reading":"liè","description":"liè：寒冷凛～。～～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冽"},{"id":"glyph-seal-51c0","script":"seal","character":"净","reading":"jìng；chēng","description":"jìng：(1)清洁～化。～水。～土。～心（a.清净的心；b.心里没有牵挂）。～院（佛寺。亦称净宇”）。干～。洁～。窗明几～。\n(2)使干净～面。～手（大小便）。\n(3)空，什么也没有～尽。\n(4)单纯，纯粹的～利。～值。～价。～重（zhòng）。纯～。\n(5)单，只，全满地～是树叶。\n(6)中国传统戏剧扮演男人的角色名～角（亦称花脸”、黑头”）。\n洁；\n脏；\nchēng：冷的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-净"},{"id":"glyph-seal-51c4","script":"seal","character":"凄","reading":"qī","description":"qī：(1)寒冷风雨～～。～风苦雨。～清。～寒。\n(2)悲伤～惨。～恻。～楚。～怆。～然。～切。～怨。～厉。～咽。～婉。\n(3)冷落静寂～凉。～寂。～艳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凄"},{"id":"glyph-seal-51c6","script":"seal","character":"准","reading":"zhǔn","description":"公文用语\n决定,必定\n折充;抵充\n新旧钱暂兼行,新钱\n⒈允许，许可～许。～假。照～。\n⒉依照，按照～此制作。\n⒊跟某类事物相似的～平原。\n⒋法则，标准～则。按此为～。\n⒌通\"埻\"。箭靶。\n⒍测定水平的东西～绳。水～。\n⒎正确～确。说得～。放之四海皆～。\n⒏一定，确实她～来。～能按时到达。\n⒑把握这件事我没～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-准"},{"id":"glyph-seal-51c9","script":"seal","character":"凉","reading":"liáng；liàng","description":"liáng：(1)温度低～快。～爽。～意。～气。阴～。～丝丝。～亭。荒～。\n(2)喻灰心，失望听到这消息，我～了半截。\n(3)中国西晋末年至北魏，各族统治者在西北地区建立的割据政权五～（前、后、南、北、西）。\n冷；\n热；\nliàng：放一会儿，使温度降低把开水～一～再喝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凉"},{"id":"glyph-seal-51cb","script":"seal","character":"凋","reading":"diāo","description":"diāo：衰落～谢。～残。～枯。～萎。～零。～敝。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凋"},{"id":"glyph-seal-51cc","script":"seal","character":"凌","reading":"líng","description":"líng：(1)冰冰～。～锥。滴水成～。\n(2)侵犯、欺压欺～。～逼。～辱。～侮。恃强～弱。\n(3)杂乱，交错～乱。～杂。\n(4)升，高出～云。～霄。～空。～虚。～驾。会当～绝顶，一览众山小”。\n(5)渡过，越过虽有江河之险则～之”。\n(6)迫近，逼近～晨。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-凌"},{"id":"glyph-seal-51cf","script":"seal","character":"减","reading":"jiǎn","description":"jiǎn：(1)由原有数量中去掉一部分～价。～员。缩～。削～。偷工～料。\n(2)降低程度，衰退～轻。～弱。～少。～色。～产。～免。～缓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-减"}];
